{"model":{"datasource":{"type":"prometheus","uid":"mimir"},"expr":"sum by (cluster, namespace, deployment) (
  label_replace(
    label_replace(
      sum by (cluster, namespace, pod)(rate(container_cpu_usage_seconds_total[1m])),
      "deployment", "$1", "pod", "(.*)-(?:([0-9]+)|([a-z0-9]+)-([a-z0-9]+))"
    ),
    # The question mark in "(.*?)" is used to make it non-greedy, otherwise it
    # always matches everything and the (optional) zone is not removed.
    "deployment", "$1", "deployment", "(.*?)(?:-zone-[a-z])?"
  )
)","instant":true,"intervalMs":1000,"maxDataPoints":43200,"range":false,"refId":"A"},"source":true,"datasource_uid":"mimir","query_type":"","relative_time_range":{"from":"10m0s","to":"0s"}}
